    def check_dongle_is_detected(self, max_attempts=2):
        """
        Function to check if dongle is detected
        """
        attempt = 1
        while attempt <= max_attempts:
            logger.info('Checking if dongle detected: Attempt {}'.format(attempt))
            # Select dongle via the tray
            if self._check_dongle_is_listed_in_usb():
                logger.info('Dongle detected')
                return
            else:
                attempt += 1
                logger.info('Dongle Not detected')
                time.sleep(5)
        raise DongleNotDetectedException

