    def start_quectel_command(self, max_attempts=3):
        """
        This method starts quectel command.
        """
        cmd = self._get_pppd_cmd()
        attempt = 1
        while attempt <= max_attempts:
            logger.debug('\t' + '#' * 15 + ' Get PPP Interface attempt: {} of {} '
                         .format(attempt, max_attempts))
            self.quectel_pid = self.execute_command(cmd)
            self.quectel_pid = self.quectel_pid.rstrip()
            logger.debug("Quectel PPP Process ID: {0}".format(self.quectel_pid))
            time.sleep(20)
            ppp_log = self.execute_command('cat /home/pi/ppp_fw.log')
            self._check_ppp_log_for_possible_error(ppp_log)
            self.ppp_interface = re.findall(r'Connect: (ppp\d+) <--> {}'.format(self.tty_path),
                                            ppp_log)
            if len(self.ppp_interface) > 0:
                self.ppp_interface = self.ppp_interface[0]
                return
            else:
                attempt += 1
                self.stop_quectel_command()
                time.sleep(15)
                continue
        raise Exception('ppp interface not found in ppp log')

    def _check_ppp_log_for_possible_error(self, ppp_log):
        possible_error = {"Modem hangup": ModemHungupError,
                          "Connect script failed": PPPConnectScriptFailedError}
        for _error in possible_error:
            error_found = re.findall(_error, ppp_log)
            if len(error_found) > 0:
                logger.warn("Error {} during quectel PPP creation.".format(error_found))
                raise possible_error[_error]

    def _get_pid(self, process_name):
        process_ids = []
        console_output = self.execute_command('ps -ef | grep {}'.format(process_name))
        [process_ids.append(item.split()[1]) for item in console_output.splitlines()
         if 'grep' not in item]
        logger.debug("***************** process id {} of {} **********".format(process_ids,
                                                                               process_name))
        return process_ids

    def _get_pppd_cmd(self):
        # cmd = 'cd /etc/ppp/peers; sudo pppd call quectel-ppp > /home/pi/ppp_fw.log 2>&1 & echo $!'
        cmd = 'cd /etc/ppp/peers; sudo pppd call quectel-ppp {} > /home/pi/ppp_fw.log 2>&1 & ' \
              'echo $!'.format(self.tty_path)
        if self.ipv4_or_v6.lower() == 'ipv6':
            cmd = 'cd /etc/ppp/peers; sudo pppd call quectel-ppp +ipv6 {} > /home/pi/ppp_fw.log ' \
                  '2>&1 & echo $!'.format(self.tty_path)
        logger.debug('quectel command: {}'.format(cmd))
        # global quectel_pid
        # quectel_pid = self.execute_command(cmd)
        return cmd

    def stop_quectel_command(self, kill_all_dependent_process=False):
        """
        Function to stop quectel command
        """
        # global quectel_pid
        logger.debug('Stopping Quectel Daemon')
        if self.quectel_pid and self.quectel_pid != '':
            logger.debug("Quectel PPP Process ID: {0}".format(self.quectel_pid))
            self.execute_command('ps -p {} | grep {}'.format(self.quectel_pid, self.quectel_pid))
            self.execute_command('sudo kill -2 {}'.format(self.quectel_pid))
            self.quectel_pid = None
        logger.debug('No Quectel Daemon Running.')
        logger.debug('Checking if any serial2tcp or ppp process is running')
        serial2tcp_process = self._get_pid('serial2tcp')
        ppp_process = self._get_pid('ppp')
        if kill_all_dependent_process:
            for item in serial2tcp_process:
                self.execute_command('sudo kill -2 {}'.format(item))
            for item in ppp_process:
                self.execute_command('sudo kill -2 {}'.format(item))

    def upload_file_to_host(self, source, target):
        """
        Function to upload file to host
        """
        self.ssh_to_device_host.open_sftp().put(source, target)

    def get_ip_address(self):
        """
        Function to get IP address
        """
        console_output = self.execute_command('sudo ifconfig -a')
        try:
            console_output = self.execute_command('sudo ifconfig {}'.format(self.ppp_interface))
            ipv4_regex = r'inet (addr:)?\s*:?\s*(.*?)(/\d+)?\s+'
            ipv6_regex = r'inet6 (addr\s*:)?\s*(.*?)(/\d+)?\s*scope:?global'
            ip_matches = []
            for regex in [ipv6_regex, ipv4_regex]:
                ip_matches = re.findall(regex, console_output, re.I)
                if ip_matches:
                    break
            logger.debug("UE IP match: {0}".format(str(ip_matches)))
            if len(ip_matches) > 0:
                logger.info("UE IP: {0}".format(ip_matches[0][:]))
                return ip_matches[0][1]
            else:
                raise IpNotFoundException()
        except Exception:
            raise IpNotFoundException()

    def _check_dongle_is_listed_in_usb(self):
        logger.info("Checking if dongle is listed in USB...")
        cmd = "lsusb | grep {}:{} | wc -l"
        console_output = self.execute_command(cmd.format(self.product_id, self.device_id))
        logger.debug(console_output)
        if int(console_output) > 0:
            return True
        return False

    def _reset_interface(self, interface):
        self.execute_command("sudo ifconfig {} down".format(interface))
        time.sleep(5)
        self.execute_command("sudo ifconfig {} up".format(interface))
        time.sleep(10)

    def execute_command(self, command):
        """
        Function to execute at command
        """
        logger.debug(command)
        try:
            stdin, stdout, stderr = self.ssh_to_device_host.exec_command(command)
            console_output = decode_str(stdout.read())
            status = stdout.channel.recv_exit_status()
            logger.debug("Command Output:\n{}\n".format(console_output))
            if status == 0:
                return console_output
            else:
                logger.error("Command execution failed: Return code{}".format(status))
                logger.error(str(stderr.readlines()))
        except Exception:
            logger.error("Failed in command execution: {}".format(command))
            raise Exception()

    def get_all_ttyUSBdevices(self, last_tty_devices):
        """
        Function to get all tty USB devices
        """
        refreshed_tty_devices_list = []
        # console_output = self.execute_command("ls /dev/ttyUSB*")
        logger.debug("last_tty_devices {}".format(last_tty_devices))
        console_output = self.execute_command(
            "ls /dev/serial/by-path/platform-3f980000.usb-usb*.2-port0")
        if console_output:
            refreshed_tty_devices_list = re.split(r'\s+', console_output)
            refreshed_tty_devices_list.pop()
            if len(refreshed_tty_devices_list) == 0:
                raise Exception('No ttyUSB devices found')
            else:
                logger.debug('Available ttyUSBports: {}'.format(str(refreshed_tty_devices_list)))
                refreshed_tty_devices_list.reverse()
                return refreshed_tty_devices_list
        else:
            raise Exception('No ttyUSB devices found')
